## 四、MCP Server 开发
### 4.1 Python MCP Server（stdio）
```python
import asyncio
from mcp.server import Server
from mcp.server.stdio import stdio_server
from mcp.types import TextContent

server = Server("enterprise-knowledge-server")

async def similarity_search(query: str, limit: int):
    # 示例中用伪实现代替真实向量库调用
    return [
        {"source": "handbook.md", "content": f"与 {query} 相关的知识片段"}
    ][:limit]

@server.tool()
async def search_knowledge(query: str, max_results: int = 5) -> list[TextContent]:
    """在企业知识库中搜索相关文档。"""
    docs = await similarity_search(query, max_results)
    return [
        TextContent(
            type="text",
            text=f"来源: {doc['source']}\n内容: {doc['content']}",
        )
        for doc in docs
    ]

@server.resource("config://database")
async def get_database_config() -> str:
    """暴露只读配置资源。"""
    return "readonly=true; poolSize=8"

async def main() -> None:
    async with stdio_server() as (read_stream, write_stream):
        await server.run(
            read_stream,
            write_stream,
            server.create_initialization_options(),
        )

if __name__ == "__main__":
    asyncio.run(main())
```

### 4.2 TypeScript MCP Server
```typescript
import { Server } from "@modelcontextprotocol/sdk/server/index.js";
import { StdioServerTransport } from "@modelcontextprotocol/sdk/server/stdio.js";
import {
  CallToolRequestSchema,
  ListToolsRequestSchema,
} from "@modelcontextprotocol/sdk/types.js";

const server = new Server(
  { name: "knowledge-server", version: "1.0.0" },
  { capabilities: { tools: {} } }
);

server.setRequestHandler(ListToolsRequestSchema, async () => ({
  tools: [
    {
      name: "search_knowledge",
      description: "在企业知识库中搜索相关文档",
      inputSchema: {
        type: "object",
        properties: {
          query: { type: "string", description: "搜索关键词" },
          maxResults: { type: "number", default: 5 }
        },
        required: ["query"]
      }
    }
  ]
}));

server.setRequestHandler(CallToolRequestSchema, async (request) => {
  const { name, arguments: args } = request.params;
  if (name !== "search_knowledge") throw new Error("Unknown tool: " + name);
  const results = await searchKnowledge(args.query, args.maxResults ?? 5);
  return { content: [{ type: "text", text: JSON.stringify(results) }] };
});

const transport = new StdioServerTransport();
await server.connect(transport);
```

## 五、安全与生产化
### 5.1 权限控制与脱敏
```python
import re
from mcp.types import TextContent

ALLOWED_TOOLS = {"search_knowledge", "get_public_doc"}
ADMIN_TOOLS = {"delete_document", "update_config"}

async def check_permission(tool_name: str, user_role: str) -> bool:
    if tool_name in ALLOWED_TOOLS:
        return True
    return tool_name in ADMIN_TOOLS and user_role == "admin"

def sanitize_content(content: str) -> str:
    content = re.sub(r"\b1[3-9]\d{9}\b", "***", content)
    return re.sub(r"\b[\w.-]+@[\w.-]+\.\w+\b", "***@***.com", content)

@server.tool()
async def safe_search(query: str, user_role: str = "user") -> list[TextContent]:
    if not await check_permission("search_knowledge", user_role):
        return [TextContent(type="text", text="无权调用该工具")]
    docs = await similarity_search(query, 5)
    return [TextContent(type="text", text=sanitize_content(doc["content"])) for doc in docs]
```

## 六、MCP 生态定位
MCP 面向 AI 应用集成，核心抽象是 Tools、Resources、Prompts。传输层以本地 stdio 和远程 Streamable HTTP 为主；旧 HTTP+SSE 属历史方案，新系统应优先使用 Streamable HTTP，并在远程部署时补齐 OAuth、审计、限流和租户隔离。
